// ====== Xác định KỲ BÁO CÁO theo giờ VN ======
// Ngày 1 hằng tháng → THANG (ngày 1 của T1/4/7/10 → QUY, gộp cả quý trước).
// Thứ 2 hằng tuần → TUAN (tuần trước, T2→CN).
const VN = 7 * 3600 * 1000;
const now = new Date(Date.now() + VN); // 'giờ VN' trên trục UTC
const d = (x) => x.toISOString().slice(0, 10);
const utc = (y, m, day) => new Date(Date.UTC(y, m, day));
let ky, tu, den, nhan;
if (now.getUTCDate() === 1) {
  const th = now.getUTCMonth(); // 0-11, tháng hiện tại (đầu tháng)
  if ([0, 3, 6, 9].includes(th)) {
    ky = 'QUY';
    const qEndMonth = th; // tháng đầu quý mới → quý trước kết thúc tháng th-1
    den = d(utc(now.getUTCFullYear(), qEndMonth, 0));
    tu = d(utc(now.getUTCFullYear(), qEndMonth - 3, 1));
    nhan = `QUÝ ${Math.floor((qEndMonth - 3) / 3) + 1}/${new Date(tu).getUTCFullYear()}`;
  } else {
    ky = 'THANG';
    den = d(utc(now.getUTCFullYear(), th, 0));
    tu = d(utc(now.getUTCFullYear(), th - 1, 1));
    nhan = `THÁNG ${String(th === 0 ? 12 : th).padStart(2, '0')}/${new Date(tu).getUTCFullYear()}`;
  }
} else {
  ky = 'TUAN';
  const dow = now.getUTCDay() || 7; // 1=T2
  const mon = utc(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - dow + 1 - 7);
  const sun = utc(mon.getUTCFullYear(), mon.getUTCMonth(), mon.getUTCDate() + 6);
  tu = d(mon); den = d(sun);
  // số tuần ISO gần đúng
  const jan1 = utc(mon.getUTCFullYear(), 0, 1);
  const tuanSo = Math.ceil(((mon - jan1) / 86400000 + jan1.getUTCDay() + 1) / 7);
  nhan = `TUẦN ${tuanSo}/${mon.getUTCFullYear()}`;
}
const maLanChay = `WF5-${ky}-${den}-${$execution.id}`;
return [{ json: {
  ky, tu, den, ky_bao_cao: nhan,
  tu_hienthi: tu.split('-').reverse().join('/'), den_hienthi: den.split('-').reverse().join('/'),
  tao_luc: new Date(Date.now() + VN).toISOString().slice(0, 16).replace('T', ' '),
  ma_lan_chay: maLanChay,
  ten_file: `BaoCao-GMP-${ky}-${den}`,
} }];

// ====== Chuẩn bị: parse JSON RPC + danh sách biểu đồ cho /render-batch ======
const meta = $('Xác định kỳ').first().json;
const bc = JSON.parse($json.bao_cao); // toàn bộ số liệu — 1 nguồn duy nhất
const mau = (v) => (v == null ? '#94a3b8' : v >= 95 ? '#0d9488' : v >= 80 ? '#d97706' : '#b91c1c');
const items = [];
const lineData = (bc.xu_huong?.nha_may || bc.chuoi_ngay || []).map((r) => ({ label: (r.ngay || '').slice(5).split('-').reverse().join('/'), value: r.ty_le }));
items.push({ key: 'chart_line', type: 'line', data: lineData, options: { markLine80: true }, width: 1200, height: 340 });
items.push({ key: 'chart_line_email', type: 'line', data: lineData, options: { markLine80: true }, width: 900, height: 280 });
items.push({ key: 'chart_heat', type: 'calendarHeatmap', data: (bc.xu_huong?.nha_may || bc.chuoi_ngay || []).map((r) => ({ ngay: r.ngay, gia_tri: r.ty_le })), width: 1200, height: 260 });
for (const ph of (bc.top_phong_xau || bc.top_phong_rui_ro || [])) items.push({ key: `spark_xau_${ph.ma_phong}`, type: 'sparkline', data: (ph.chuoi || []).map((r) => ({ label: r.ngay, value: r.ty_le })), width: 240, height: 72 });
for (const ph of (bc.top_phong_tot || [])) items.push({ key: `spark_tot_${ph.ma_phong}`, type: 'sparkline', data: (ph.chuoi || []).map((r) => ({ label: r.ngay, value: r.ty_le })), width: 240, height: 72 });
for (const k of (bc.xu_huong?.theo_khu || [])) items.push({ key: `khu_${k.khu_vuc}`, type: 'sparkline', data: (k.chuoi || []).map((r) => ({ label: r.ngay, value: r.ty_le })), width: 320, height: 90 });
for (const a of (bc.xu_huong?.theo_ahu || [])) items.push({ key: `ahu_${a.ahu}`, type: 'sparkline', data: (a.chuoi || []).map((r) => ({ label: r.ngay, value: r.ty_le })), width: 320, height: 90 });
return [{ json: { ...meta, bao_cao: bc, render_items: items, mau_fn_ghi_chu: 'mau() tính lại ở node Ráp' } }];

// ====== RÁP BÁO CÁO: thay placeholder + nhân bản {{#each}} ======
const all = $input.all();
const nguon = Object.assign({}, ...all.map((i) => i.json));
const meta = $('Chuẩn bị biểu đồ').first().json;
const bc = meta.bao_cao;
const anh = nguon.images || {};
let tplChiTiet = nguon.tpl_chi_tiet;
let tplEmail = nguon.tpl_email;
if (!tplChiTiet || !tplEmail) throw new Error('Thiếu template từ GitHub — kiểm tra 2 node Tải template');
const mau = (v) => (v == null ? '#94a3b8' : v >= 95 ? '#0d9488' : v >= 80 ? '#d97706' : '#b91c1c');
const fmt = (v, d = 1) => (v == null ? '—' : (+v).toFixed(d));
const muiTen = (v) => (v == null ? '' : v > 0 ? '▲' : v < 0 ? '▼' : '＝');
const deltaMau = (v, totKhiTang) => (v == null ? '#64748b' : (totKhiTang ? v >= 0 : v <= 0) ? '#0d9488' : '#b91c1c');
// ---- KPI + delta ----
const k1 = bc.kpi_ky_nay || {}, k0 = bc.kpi_ky_truoc || {};
const dTuanThu = (k1.ty_le_tuan_thu != null && k0.ty_le_tuan_thu != null) ? +(k1.ty_le_tuan_thu - k0.ty_le_tuan_thu).toFixed(1) : null;
const dOos = (k1.so_gio_oos != null && k0.so_gio_oos != null) ? +(k1.so_gio_oos - k0.so_gio_oos).toFixed(1) : null;
const dSuCo = (k1.so_su_co != null && k0.so_su_co != null) ? (k1.so_su_co - k0.so_su_co) : null;
const dq = bc.do_phu_du_lieu || {};
const mktMax = (bc.mkt || [])[0] || {};
const batThuong = bc.phong_xau_bat_thuong || [];
const ngoaiLe = bc.ngoai_le || { tong_so: 0, theo_loai: [], chi_tiet: [] };
const LOAI_VI = { SENSOR_DUNG_HINH: 'Cảm biến đứng hình (giá trị không đổi bất thường)', FMS_HTTP_LOI: 'Lỗi kết nối FMS (mất phiên lấy dữ liệu)', MAT_DU_LIEU: 'Khoảng trống dữ liệu' };
const rep = {
  ky: meta.ky, ky_bao_cao: meta.ky_bao_cao, tu_ngay: meta.tu_hienthi, den_ngay: meta.den_hienthi,
  tu_ngay_iso: meta.tu, den_ngay_iso: meta.den, tao_luc: meta.tao_luc, ma_lan_chay: meta.ma_lan_chay,
  ten_file_pdf: meta.ten_file + '.pdf', logo_src: anh.logo || '',
  kpi_tuan_thu: fmt(k1.ty_le_tuan_thu), kpi_tuan_thu_mau: mau(k1.ty_le_tuan_thu),
  delta_tuan_thu: (dTuanThu == null ? '—' : (dTuanThu > 0 ? '+' : '') + dTuanThu + '%'), delta_tuan_thu_mau: deltaMau(dTuanThu, true), delta_tuan_thu_mui_ten: muiTen(dTuanThu),
  kpi_gio_oos: fmt(k1.so_gio_oos, 0) + 'h', delta_oos: (dOos == null ? '—' : (dOos > 0 ? '+' : '') + dOos + 'h'), delta_oos_mau: deltaMau(dOos, false), delta_oos_mui_ten: muiTen(dOos),
  so_su_co_mo: k1.so_su_co_mo ?? '—', so_su_co_dong: k1.so_su_co_dong ?? '—', delta_su_co: (dSuCo == null ? '—' : (dSuCo > 0 ? '+' : '') + dSuCo), delta_su_co_mau: deltaMau(dSuCo, false), delta_su_co_mui_ten: muiTen(dSuCo), mttr_gio: fmt(k1.mttr_gio),
  so_tin_hieu_spc: (bc.spc || {}).tong_tin_hieu ?? 0, kpi_spc_mau: ((bc.spc || {}).tong_tin_hieu || 0) > 0 ? '#d97706' : '#0d9488', so_scope_ngoai_ks: (bc.spc || {}).so_scope_ngoai_kiem_soat ?? 0,
  kpi_dq: fmt(dq.dq_tb_pct), kpi_dq_mau: mau(dq.dq_tb_pct), so_ngay_thieu_dl: dq.so_ngay_thieu ?? '—',
  phong_thieu_dl: (dq.phong_thieu_nhat || []).map((p) => `${p.ma_phong} (${fmt(p.dq_pct)}%)`).join(', ') || '—',
  kpi_mkt_max: fmt(mktMax.mkt, 2), kpi_mkt_mau: mktMax.mkt != null && mktMax.mkt > 25 ? '#b91c1c' : '#0f172a', kpi_mkt_phong: mktMax.ma_phong || '—',
  chart_line_src: anh.chart_line || '', chart_heat_src: anh.chart_heat || '',
  nhan_dinh_ai: (bc.nhan_dinh_ai_gan_nhat || {}).noi_dung || 'Chưa có nhận định AI trong kỳ.',
  ai_model_dung: (bc.nhan_dinh_ai_gan_nhat || {}).model_dung || '—', ai_tao_luc: (bc.nhan_dinh_ai_gan_nhat || {}).tao_luc || '—',
  so_phong_bat_thuong: batThuong.length, so_ngoai_le: ngoaiLe.tong_so ?? 0,
  ket_luan_kiem_soat: (((bc.spc || {}).tong_tin_hieu || 0) === 0 && batThuong.length === 0) ? 'Duy trì trạng thái kiểm soát trong kỳ — không có tín hiệu SPC, không có phòng xấu đi bất thường.' : `CÓ XU HƯỚNG BẤT LỢI cần điều tra: ${(bc.spc || {}).tong_tin_hieu || 0} tín hiệu SPC, ${batThuong.length} phòng xấu đi bất thường (mục 6) — QA lập phiếu điều tra/deviation trước kỳ tiếp theo.`,
  tom_tat_dieu_hanh: `Kỳ ${meta.ky_bao_cao}: tuân thủ toàn nhà máy ${fmt(k1.ty_le_tuan_thu)}% (${dTuanThu == null ? 'không so được kỳ trước' : (dTuanThu >= 0 ? 'tăng ' : 'giảm ') + Math.abs(dTuanThu) + ' điểm so kỳ trước'}), ${fmt(k1.so_gio_oos, 0)} giờ OOS, ${k1.so_su_co_mo ?? 0} sự cố đang mở. ${batThuong.length ? '⚠ ' + batThuong.length + ' phòng xấu đi bất thường cần rà soát (mục 6).' : 'Không phát hiện phòng xấu đi bất thường.'} ${((bc.spc || {}).tong_tin_hieu || 0) > 0 ? (bc.spc.tong_tin_hieu + ' tín hiệu SPC cần theo dõi.') : 'SPC trong kiểm soát.'}`,
};
// ---- Khối lặp ----
const each = (tpl, ten, rows, build) => tpl.replace(new RegExp(`\\{\\{#each ${ten}\\}\\}([\\s\\S]*?)\\{\\{\\/each\\}\\}`), (_, than) => rows.map((r) => build(than, r)).join(''));
const thay = (than, obj) => Object.entries(obj).reduce((s, [k, v]) => s.replaceAll(`{{${k}}}`, String(v ?? '—')), than);
const topXau = (bc.top_phong_xau || bc.top_phong_rui_ro || []).slice(0, 5);
const topTot = (bc.top_phong_tot || []).slice(0, 5);
tplChiTiet = each(tplChiTiet, 'top_phong_xau', topXau, (t, r) => thay(t, { ...r, ty_le_tuan_thu: fmt(r.ty_le_tuan_thu), so_gio_oos: fmt(r.so_gio_oos), mau: mau(r.ty_le_tuan_thu), spark_src: anh[`spark_xau_${r.ma_phong}`] || '' }));
tplChiTiet = each(tplChiTiet, 'top_phong_tot', topTot, (t, r) => thay(t, { ...r, ty_le_tuan_thu: fmt(r.ty_le_tuan_thu), so_gio_oos: fmt(r.so_gio_oos), spark_src: anh[`spark_tot_${r.ma_phong}`] || '' }));
tplChiTiet = each(tplChiTiet, 'xu_huong_khu', bc.xu_huong?.theo_khu || [], (t, r) => thay(t, { khu_vuc: r.khu_vuc, ty_le_tb: fmt(r.ty_le_tb), mau: mau(r.ty_le_tb), mini_src: anh[`khu_${r.khu_vuc}`] || '' }));
tplChiTiet = each(tplChiTiet, 'xu_huong_ahu', bc.xu_huong?.theo_ahu || [], (t, r) => thay(t, { ahu: r.ahu, ty_le_tb: fmt(r.ty_le_tb), mau: mau(r.ty_le_tb), mini_src: anh[`ahu_${r.ahu}`] || '' }));
tplChiTiet = each(tplChiTiet, 'phong_xau_bat_thuong', batThuong, (t, r) => thay(t, { ...r, tuan_thu_ky_nay: fmt(r.tuan_thu_ky_nay), tuan_thu_ky_truoc: fmt(r.tuan_thu_ky_truoc), delta: (r.delta > 0 ? '+' : '') + fmt(r.delta), ly_do_html: (r.ly_do || []).map((x) => `<span class="the-ly-do">${x}</span>`).join(' ') }));
tplChiTiet = each(tplChiTiet, 'ngoai_le_theo_loai', ngoaiLe.theo_loai || [], (t, r) => thay(t, { loai_vi: LOAI_VI[r.loai] || r.loai, so_lan: r.so_lan, dien_giai: r.dien_giai || '' }));
tplChiTiet = each(tplChiTiet, 'su_co_tieu_bieu', (bc.su_co || {}).tieu_bieu || [], (t, r) => thay(t, r));
tplChiTiet = each(tplChiTiet, 'spc_chi_tiet', (bc.spc || {}).chi_tiet || [], (t, r) => thay(t, r));
tplChiTiet = each(tplChiTiet, 'mkt_chi_tiet', (bc.mkt || []).slice(0, 10), (t, r) => thay(t, { ...r, mkt: fmt(r.mkt, 2), t_tb: fmt(r.t_tb, 2), t_max: fmt(r.t_max, 2) }));
tplChiTiet = each(tplChiTiet, 'gioi_han_tham_chieu', bc.gioi_han_tham_chieu || [], (t, r) => thay(t, r));
tplChiTiet = thay(tplChiTiet, rep);
// ---- Email (tóm tắt): line chart nhẹ + bảng, KHÔNG heatmap/spark ----
tplEmail = each(tplEmail, 'top_phong_xau', topXau, (t, r) => thay(t, { ...r, ty_le_tuan_thu: fmt(r.ty_le_tuan_thu), so_gio_oos: fmt(r.so_gio_oos), mau: mau(r.ty_le_tuan_thu), delta: (r.delta_ky_truoc == null ? '—' : (r.delta_ky_truoc > 0 ? '+' : '') + fmt(r.delta_ky_truoc) + '%'), delta_mau: deltaMau(r.delta_ky_truoc, true) }));
tplEmail = each(tplEmail, 'bat_thuong_tom_tat', batThuong.slice(0, 5), (t, r) => thay(t, { ...r, tuan_thu_ky_nay: fmt(r.tuan_thu_ky_nay), delta: (r.delta > 0 ? '+' : '') + fmt(r.delta) + '%', ly_do: (r.ly_do || []).join(' · ') }));
tplEmail = thay(tplEmail, { ...rep, chart_line_src: anh.chart_line_email || anh.chart_line || '' });
const binHtml = await this.helpers.prepareBinaryData(Buffer.from(tplChiTiet, 'utf8'), meta.ten_file + '.html', 'text/html');
return [{ json: { ...meta, html_email: tplEmail, tieu_de_email: `[BMS-GMP] Báo cáo ${meta.ky_bao_cao} — tuân thủ ${rep.kpi_tuan_thu}% ${rep.delta_tuan_thu_mui_ten}${rep.delta_tuan_thu}` }, binary: { bao_cao_html: binHtml } }];
